import itertools
import json

def solve():
    houses = [1, 2, 3]

    categories = ["Name", "Vacation", "Height", "Flower", "HairColor", "Education"]
    values = {
        "Name": ["Eric", "Arnold", "Peter"],
        "Vacation": ["mountain", "city", "beach"],
        "Height": ["very short", "average", "short"],
        "Flower": ["carnations", "daffodils", "lilies"],
        "HairColor": ["brown", "black", "blonde"],
        "Education": ["associate", "bachelor", "high school"],
    }

    # Helper to get index of a specific value in a category assignment
    def idx(current, cat, val):
        if cat not in current:
            return None
        return current[cat].index(val)

    # Consistency check with given clues
    def consistent(current):
        # 1. Peter is the person who has an average height.
        if "Name" in current and "Height" in current:
            if idx(current, "Name", "Peter") != idx(current, "Height", "average"):
                return False

        # 2. The person who loves a bouquet of daffodils is Arnold.
        if "Name" in current and "Flower" in current:
            if idx(current, "Name", "Arnold") != idx(current, "Flower", "daffodils"):
                return False

        # 3. The person who is very short is not in the second house.
        if "Height" in current:
            if current["Height"][1] == "very short":
                return False

        # 4. The person who loves beach vacations is in the first house.
        if "Vacation" in current:
            if current["Vacation"][0] != "beach":
                return False

        # 5. The person with a high school diploma is in the third house.
        if "Education" in current:
            if current["Education"][2] != "high school":
                return False

        # 6. The person who is short is somewhere to the right of the person who is very short.
        if "Height" in current:
            if idx(current, "Height", "short") <= idx(current, "Height", "very short"):
                return False

        # 7. The person who loves the boquet of lilies is Eric.
        if "Name" in current and "Flower" in current:
            if idx(current, "Name", "Eric") != idx(current, "Flower", "lilies"):
                return False

        # 8. The person who loves the boquet of lilies is the person with a bachelor's degree.
        if "Flower" in current and "Education" in current:
            if idx(current, "Flower", "lilies") != idx(current, "Education", "bachelor"):
                return False

        # 9. The person who prefers city breaks is somewhere to the right of Peter.
        if "Vacation" in current and "Name" in current:
            if not (idx(current, "Vacation", "city") > idx(current, "Name", "Peter")):
                return False

        # 10. The person who has blonde hair is in the third house.
        if "HairColor" in current:
            if current["HairColor"][2] != "blonde":
                return False

        # 11. The person who loves beach vacations is the person who has brown hair.
        # Since beach is in house 1 (clue 4), brown hair must also be in house 1.
        if "HairColor" in current:
            if idx(current, "HairColor", "brown") != 0:
                return False
        if "Vacation" in current and "HairColor" in current:
            if idx(current, "Vacation", "beach") != idx(current, "HairColor", "brown"):
                return False

        return True

    # Backtracking search
    cat_order = ["Vacation", "HairColor", "Education", "Height", "Name", "Flower"]

    def backtrack(i, current):
        if i == len(cat_order):
            if consistent(current):
                return current
            return None

        cat = cat_order[i]
        for perm in itertools.permutations(values[cat]):
            current[cat] = list(perm)
            if consistent(current):
                res = backtrack(i + 1, current)
                if res is not None:
                    return res
            del current[cat]
        return None

    assignment = backtrack(0, {})

    if assignment is None:
        raise RuntimeError("No solution found")

    header = ["House", "Name", "Vacation", "Height", "Flower", "HairColor", "Education"]
    rows = []
    for i in range(3):
        row = [
            str(i + 1),
            assignment["Name"][i],
            assignment["Vacation"][i],
            assignment["Height"][i],
            assignment["Flower"][i],
            assignment["HairColor"][i],
            assignment["Education"][i],
        ]
        rows.append(row)

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    solve()
